EXPORT ZZT_ENCSHAPE()
BEGIN
  LOCAL R,I,T,K,D;
  HComplex:=1;
  R:=stddev([[0+1,4],[3,8],[5,12]],[[0-1,1,1],[3,1,1]]);
  I:=stddev([[0+6,9]],[[0+2],[-1]]);
  T:=stddev([[0+1,4,6],[3,8,9]],[[0-1,1],[3,1],[1,1]]);
  K:=stddev([[0+1,4],[3,8]],[[-1,1],[3,1]]);
  D:=stddev([[0+1,4],[3,8]],[[-1,1],[3,1],[1,1]]);
  L1:={R,I,T,K,D};
  RETURN {{TYPE(R),STRING(R),TYPE(approx(R)),ROUND(RE(approx(R)),8)},
          {TYPE(I),STRING(I),TYPE(approx(I)),ROUND(IM(approx(I)),8)},
          {TYPE(T),STRING(T),ROUND(RE(approx(T)),8)},
          {TYPE(K),STRING(K)},
          {TYPE(D),D,INSTRING(D,CHAR(10))}};
END;

EXPORT ZZT_ENCSHAPE()
BEGIN
  LOCAL R:=L1(1),I:=L1(2),T:=L1(3),K:=L1(4),D:=L1(5);
  RETURN {{TYPE(R),STRING(R),TYPE(approx(R)),ROUND(RE(approx(R)),8)},
          {TYPE(I),STRING(I),TYPE(approx(I)),ROUND(IM(approx(I)),8)},
          {TYPE(T),STRING(T),ROUND(RE(approx(T)),8)},
          {TYPE(K),STRING(K)},
          {TYPE(D),D,INSTRING(D,CHAR(10))}};
END;

